//! Executes Lua generated by `lua-transpiler`, driven by
//! [`DebugCommand`]s and reporting [`RunEvent`]s — the `runtime` side of
//! the contract in `docs/technical-design.md`.
//!
//! # Why this doesn't use Lua `debug` hooks
//!
//! The execution runtime decision (`docs/technical-design.md`) embeds
//! [piccolo](https://docs.rs/piccolo), a pure-Rust Lua VM chosen after a
//! spike (Phase 0) found `mlua`/`rlua` can't build for Dioxus Web's
//! `wasm32-unknown-unknown` target. piccolo has no `debug` library and —
//! confirmed by inspecting its public API before writing this crate —
//! exposes no way at all to inspect a paused frame's position or local
//! variables from outside a callback.
//!
//! So this crate doesn't try to. `lua-transpiler` emits a call to
//! `__blok_mark(id, name, value, ...)` before every statement, reporting
//! that statement's own [`block_ir::BlockId`] and every in-scope
//! variable's current value as plain Lua call arguments. The callback
//! registered for `__blok_mark` (see the `host` module) is the *only* place this
//! crate ever learns where execution is or what the variables are — and,
//! since it's an ordinary callback invocation, it has full access to both
//! via the call's own arguments, no VM introspection needed.
//!
//! Pausing is `CallbackReturn::Yield` from that same callback — piccolo's
//! equivalent of `coroutine.yield()`, just triggered from Rust instead of
//! from the script. Breakpoints are compared directly against the
//! `BlockId` each mark call reports; no source-map line lookup is needed
//! at pause time (contrast the source map `lua-transpiler` also produces,
//! which exists for mapping error lines, not for this).

#![deny(missing_docs)]

mod error;
mod host;
mod value;

use std::cell::RefCell;
use std::rc::Rc;

use piccolo::{Callback, Closure, Executor, Fuel, Lua, StashedExecutor};
use runtime_protocol::{DebugCommand, RunEvent};

pub use error::StartError;

use host::{HostState, RunMode};

/// VM instructions per `Executor::step` call.
const STEP_FUEL: i32 = 8192;

/// Safety cap on `step` calls per [`Runtime::send`], so a program with a
/// loop that contains no statements at all (e.g. `while true do end` —
/// nothing in its empty body ever calls `__blok_mark`, so it never yields)
/// can't hang the driving loop forever. `STEP_FUEL * MAX_STEPS` VM
/// instructions is a generous budget for anything an MVP program is
/// expected to do.
const MAX_STEPS: u32 = 20_000;

/// A running (or not-yet-started) program.
///
/// Call [`Runtime::send`] with a [`DebugCommand`] to drive it; each call
/// runs until something worth reporting happens and returns the
/// [`RunEvent`]s produced along the way.
pub struct Runtime {
    lua: Lua,
    executor: StashedExecutor,
    host: Rc<RefCell<HostState>>,
}

enum StepOutcome {
    KeepGoing,
    Finished,
    Paused,
    Errored(String),
}

impl Runtime {
    /// Loads `source` (as produced by `lua_transpiler::transpile`) and
    /// prepares it to run. Doesn't execute anything yet — the first
    /// [`DebugCommand::Step`] or [`DebugCommand::Continue`] sent to
    /// [`Runtime::send`] does that.
    ///
    /// # Errors
    ///
    /// Returns [`StartError`] if `source` fails to parse. `lua-transpiler`
    /// output should never trigger this in practice.
    pub fn start(source: &str) -> Result<Self, StartError> {
        let host = Rc::new(RefCell::new(HostState::new()));
        let mut lua = Lua::core();

        let host_for_setup = host.clone();
        let source = source.to_string();
        let executor = lua
            .try_enter(|ctx| {
                let host_mark = host_for_setup.clone();
                ctx.set_global(
                    "__blok_mark",
                    Callback::from_fn(&ctx, move |_ctx, _exec, mut stack| {
                        host::handle_mark(&mut stack, &host_mark)
                    }),
                )?;

                let host_print = host_for_setup.clone();
                ctx.set_global(
                    "print",
                    Callback::from_fn(&ctx, move |_ctx, _exec, mut stack| {
                        host::handle_print(&mut stack, &host_print)
                    }),
                )?;

                let host_input = host_for_setup.clone();
                ctx.set_global(
                    "read_input",
                    Callback::from_fn(&ctx, move |_ctx, _exec, mut stack| {
                        host::handle_read_input(&mut stack, &host_input)
                    }),
                )?;

                let closure = Closure::load(ctx, None, source.as_bytes())?;
                Ok(ctx.stash(Executor::start(ctx, closure.into(), ())))
            })
            .map_err(|e| StartError(e.to_string()))?;

        Ok(Runtime {
            lua,
            executor,
            host,
        })
    }

    /// Sends a command, runs until something worth reporting happens, and
    /// returns the events produced.
    ///
    /// [`DebugCommand::SetBreakpoints`] doesn't run anything — it just
    /// updates the breakpoint set for the next
    /// [`DebugCommand::Continue`] and returns no events.
    pub fn send(&mut self, command: DebugCommand) -> Vec<RunEvent> {
        match command {
            DebugCommand::SetBreakpoints(ids) => {
                self.host.borrow_mut().breakpoints = ids.into_iter().collect();
                Vec::new()
            }
            DebugCommand::Step => {
                self.host.borrow_mut().run_mode = RunMode::Step;
                self.resume(None);
                self.drive()
            }
            DebugCommand::Continue => {
                self.host.borrow_mut().run_mode = RunMode::Continue;
                self.resume(None);
                self.drive()
            }
            DebugCommand::ProvideInput(value) => {
                self.resume(Some(value));
                self.drive()
            }
        }
    }

    /// If the executor is currently suspended (paused at a mark, or
    /// waiting on `read_input`), unblocks it with `value` (becoming
    /// `read_input`'s return value) or no value. A no-op on the very
    /// first call, before anything has run yet.
    fn resume(&mut self, value: Option<String>) {
        let executor = self.executor.clone();
        self.lua.enter(|ctx| {
            let ex = ctx.fetch(&executor);
            if ex.mode() == piccolo::ExecutorMode::Suspended {
                match &value {
                    Some(s) => {
                        let v = piccolo::Value::String(piccolo::String::from_slice(&ctx, s));
                        let _ = ex.resume(ctx, v);
                    }
                    None => {
                        let _ = ex.resume(ctx, ());
                    }
                }
            }
        });
    }

    /// Steps the executor until it pauses (a mark decided to yield, or
    /// `read_input` was called), finishes, errors, or the instruction
    /// limit is hit.
    fn drive(&mut self) -> Vec<RunEvent> {
        let executor = self.executor.clone();
        let mut stopped = false;

        for _ in 0..MAX_STEPS {
            let outcome = self.lua.enter(|ctx| {
                let ex = ctx.fetch(&executor);
                match ex.mode() {
                    piccolo::ExecutorMode::Normal => {
                        let mut fuel = Fuel::with(STEP_FUEL);
                        ex.step(ctx, &mut fuel);
                        StepOutcome::KeepGoing
                    }
                    piccolo::ExecutorMode::Result => match ex.take_result::<()>(ctx) {
                        Ok(Ok(())) => match ex.mode() {
                            piccolo::ExecutorMode::Stopped => StepOutcome::Finished,
                            piccolo::ExecutorMode::Suspended => StepOutcome::Paused,
                            _ => StepOutcome::KeepGoing,
                        },
                        Ok(Err(error)) => StepOutcome::Errored(error.to_string()),
                        Err(_) => StepOutcome::KeepGoing,
                    },
                    piccolo::ExecutorMode::Stopped => StepOutcome::Finished,
                    _ => StepOutcome::KeepGoing,
                }
            });

            match outcome {
                StepOutcome::KeepGoing => continue,
                StepOutcome::Finished => {
                    self.host.borrow_mut().events.push(RunEvent::Finished);
                    stopped = true;
                    break;
                }
                StepOutcome::Errored(message) => {
                    self.host.borrow_mut().events.push(RunEvent::Error(message));
                    stopped = true;
                    break;
                }
                StepOutcome::Paused => {
                    // The callback that caused this (handle_mark or
                    // handle_read_input) already pushed its own RunEvent.
                    stopped = true;
                    break;
                }
            }
        }

        if !stopped {
            self.host.borrow_mut().events.push(RunEvent::Error(
                "program exceeded the instruction limit (possible infinite loop)".to_string(),
            ));
        }

        std::mem::take(&mut self.host.borrow_mut().events)
    }
}
